with valid as (select id, customer_id, store_id, order_date, status, channel, discount, shipping_fee - discount as shipping_fee_minus_discount, coalesce(channel, 'NONE') as channel_clean from orders where order_date >= to_date('2023-09-21')), remaining_keys as (select id from valid intersect all select id from orders where discount < 0.15), kept_rows as (select s.* from valid s inner join remaining_keys k on s.id = k.id), metrics as (select id, customer_id, order_date, status, discount, max(shipping_fee_minus_discount) over (partition by store_id, status) as store_id_max_shipping_fee_minus_discount, max(discount) over (partition by store_id) as store_id_max_discount from kept_rows), scored as (select id, customer_id, store_id_max_discount, stddev_samp(store_id_max_discount) over (partition by customer_id, status) as customer_id_stddev_samp_store_id_max_discount from metrics), enriched as (select customer_id, store_id_max_discount, rank() over (partition by customer_id order by customer_id_stddev_samp_store_id_max_discount nulls first) as customer_id_stddev_samp_store_id_max_discount_rank from scored), with_windows as (select *, sum(store_id_max_discount) over w_part as customer_id_sum_store_id_max_discount, max(customer_id_stddev_samp_store_id_max_discount_rank) over w_part as customer_id_max_customer_id_stddev_samp_store_id_max_discount_rank from enriched where customer_id is null window w_part as (partition by customer_id)), with_windows_orders as (select store_id_max_discount, customer_id_stddev_samp_store_id_max_discount_rank, round(customer_id_max_customer_id_stddev_samp_store_id_max_discount_rank / sum(customer_id_max_customer_id_stddev_samp_store_id_max_discount_rank) over (partition by customer_id), 4) as customer_id_max_customer_id_stddev_samp_store_id_max_discount_rank_share from with_windows) select store_id_max_discount, customer_id_stddev_samp_store_id_max_discount_rank, customer_id_max_customer_id_stddev_samp_store_id_max_discount_rank_share from with_windows_orders order by store_id_max_discount desc;
